{"hypotheses": [
  {
    "name": "H1",
    "mechanism": "Market overreaction to short-term momentum can be exploited by combining momentum with long-term reversal.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom6m"},
        {"weight": -0.5, "primitive": "LRreversal"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "LRreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "H2",
    "mechanism": "Firms with high asset growth tend to underperform due to market overoptimism. This effect can be enhanced with short-term reversal.",
